// ---- Step 6.5 (PROP-091): delete-propagation pass (prune-expired orphans) ----
// Runs ONLY after a successful build.js sync-workspace invocation (needSync
// branch). Deletes FUSE files that are (1) allow-listed prune-managed per-run
// artifact patterns, (2) ABSENT from git HEAD (git ls-files), AND (3) past
// their per-pattern retention window per the date embedded in the filename.
// Criterion (3) is what distinguishes "FUSE-born sentinel not yet pushed to
// git" (young — NEVER deleted) from "orphan left behind after prune-integrity
// removed it from git" (past retention — safe to delete; content survives in
// the corresponding *-archive.jsonl in git).
//
// Config: monitor/scripts/sync-workspace-step4c.config.json key
// "delete_propagation": { "enabled": false, "per_cycle_cap": 200,
//   "abort_abs": 500, "abort_pct_of_category": 50 }.
// enabled=false → manifest-only (dry-run): candidates are listed in the
// sentinel but nothing is unlinked. This is the mandatory Phase-0 state.
//
// PATTERN TABLE mirrors workspace-sync.md is_prune_expired() and
// prune-integrity.js POLICIES. If you edit one, edit all three.
const DELETE_PATTERNS = [
  { re: /^monitor\/integrity\/workspace-sync-runs\/run-.*\.json$/, days: 7 },
  { re: /^monitor\/integrity\/verify-pending-run-.*\.json$/, days: 14 },
  { re: /^monitor\/integrity\/narrative-cite-audit-.*\.json$/, days: 14 },
  { re: /^monitor\/integrity\/push-failure-.*\.json$/, days: 14 },
  { re: /^monitor\/integrity\/git-to-fuse-divergence-.*\.json$/, days: 14 },
  { re: /^monitor\/integrity\/sync-workspace-runs-.*\.json$/, days: 14 }
  // Deliberately EXCLUDED: report-*.json (90d), workspace-sync-abort-*.json
  // (30d), sync-workspace-non-ff-abort-*.json (90d) — low volume, high
  // forensic value; operator deletes manually if ever needed.
];
function dateFromName(rel) {
  const b = require('path').basename(rel);
  let m = b.match(/\d{4}-\d{2}-\d{2}/);
  if (m) return m[0];
  m = b.match(/(\d{4})(\d{2})(\d{2})T/);
  return m ? m[1]+'-'+m[2]+'-'+m[3] : null;
}
function deletePropagationPass(fuseRoot) {
  const out = { ran: false, mode: null, candidates: 0, deleted: 0, errors: 0,
                truncated: false, aborted: null, sample: [] };
  let cfg = { enabled: false, per_cycle_cap: 200, abort_abs: 500, abort_pct_of_category: 50 };
  try {
    const c = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf8'));
    if (c && typeof c.delete_propagation === 'object') cfg = { ...cfg, ...c.delete_propagation };
  } catch (e) {}
  out.mode = cfg.enabled ? 'delete' : 'manifest-only';
  // HEAD membership set — single git call, authoritative "belongs in git" test.
  const tracked = new Set(sh('git ls-files monitor/integrity').split('\n').filter(Boolean));
  // Walk FUSE monitor/integrity, collect allow-listed entries.
  const fuseDir = require('path').join(fuseRoot, 'monitor/integrity');
  let fuseFiles = [];
  const walk = d => { for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const full = require('path').join(d, e.name);
    if (e.isDirectory()) walk(full); else if (e.isFile()) fuseFiles.push(require('path').relative(fuseRoot, full)); } };
  try { walk(fuseDir); } catch (e) { out.aborted = 'fuse-walk-failed: ' + e.message; return out; }
  const inCategory = fuseFiles.filter(r => DELETE_PATTERNS.some(p => p.re.test(r)));
  const nowMs = Date.now();
  const candidates = inCategory.filter(rel => {
    if (tracked.has(rel)) return false;                       // still in git HEAD → keep
    const p = DELETE_PATTERNS.find(p => p.re.test(rel));
    const d = dateFromName(rel);
    if (!d) return false;                                     // undated → never touch
    const ageMs = nowMs - Date.parse(d);
    return isFinite(ageMs) && ageMs > (p.days + 1) * 86400000; // past retention → orphan
  });
  out.candidates = candidates.length;
  out.sample = candidates.slice(0, 20);
  // Safety gates (PROP-051 lineage, disaster-sensitivity constraint).
  const pctCap = Math.floor(inCategory.length * cfg.abort_pct_of_category / 100);
  if (candidates.length > cfg.abort_abs || (inCategory.length > 0 && candidates.length > pctCap)) {
    out.aborted = 'delete-sanity gate: ' + candidates.length + ' candidates exceeds abort_abs=' +
      cfg.abort_abs + ' or ' + cfg.abort_pct_of_category + '% of category (' + pctCap + '); zero deletions';
    return out;
  }
  out.ran = true;
  if (!cfg.enabled) return out;                               // manifest-only
  for (const rel of candidates.slice(0, cfg.per_cycle_cap)) {
    try { fs.unlinkSync(require('path').join(fuseRoot, rel)); out.deleted++; }
    catch (e) {
      out.errors++;
      if (/EPERM|EACCES|ENOTSUP|not permitted/i.test(String(e.message))) {
        out.aborted = 'unlink-unsupported-on-fuse: ' + e.message + ' — falling back to manifest-only';
        break;                                                // FUSE refuses unlink; stop trying
      }
    }
  }
  out.truncated = candidates.length > cfg.per_cycle_cap;
  return out;
}
